from research_helpers import *
a=ev('https://www.evonik.com/en/products/hc/pr_52056099.html','Commercially supplied fermentation recombinant collagen platform; clinical-study material availability is not an approved therapeutic.')
b=ev('https://www.evonik.com/en/applications/application_1384632.html','Current JeNaCell subsidiary attribution, biosynthetic cellulose fermentation and three epicite finished dressing lines explicitly reviewed.')
c=ev('https://www.evonik.com/en/applications/application_1196251.html','Current Biolys and ThreAMINO feed ingredient listings; ordinary chemically produced methionine not automatically biotechnology.')
d=ev('https://publications.evonik.com/en/media/press-releases/corporate/evonik-invests-heavily-in-biotech-101198.html','Historical TrypAMINO fermentation qualification; current marketed availability unresolved.')
e=ev('https://publications.evonik.com/en/media/press-releases/corporate/hyacare-filler-cl-the-topical-wrinkle-smoother-106552.html','HyaCare base fermentation qualification; current grade listing checked separately.')
f=ev('https://products.evonik.com/assets/15/02/24_01_187_03_Broschuere_ThreAMINO_A4_WEB_EN_Asset_3171502.pdf','Current manufacturer brochure confirms threonine fermentation production.')
products=[p('VECOLLAN','Recombinant collagen-like peptide material platform produced by fermentation; supplied for life-science development.',a,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner']),p('biocellic','Fermentation-derived biosynthetic cellulose material platform offered through JeNaCell.',b,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner'])]
for name,desc in [('epicite BALANCE','Biosynthetic-cellulose dressing line for chronic and complex wounds.'),('epicite RESCUE','Biosynthetic-cellulose dressing line for burns and acute wounds.'),('epicite CALM','Biosynthetic-cellulose dressing line for post-procedure care.')]:products.append(p(name,desc,b,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner']))
for name,desc,url in [('HyaCare','Fermentation-derived sodium hyaluronate ingredient.','https://www.evonik.com/en/products/cs/pr_52028264.html'),('HyaCare 50','Low-molecular-weight ingredient derived from fermentation hyaluronic acid.','https://www.evonik.com/en/products/cs/pr_52026139.html'),('HyaCare Filler CL MB','Formulated crosslinked fermentation-derived hyaluronic-acid ingredient.','https://www.evonik.com/en/products/cs/pr_52015070.html')]:
 src=ev(url,'Current exact ingredient grade reviewed.');products.append(p(name,desc,src,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner'],evidence=[src,e]))
products += [p('Biolys','Fermentation-derived lysine feed ingredient containing residual nutritional biomass.',c,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner']),p('ThreAMINO','Fermentation-produced threonine feed ingredient.',c,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner'],evidence=[c,f]),p('TrypAMINO','Historical fermentation-produced tryptophan feed ingredient; current availability unresolved.',d,typ='product',sub='industrial_biotechnology',roles=['commercial_partner'])]
co=dict(company_id='cmp_2f14ef78-9705-4c3e-9c9e-defc72e1e682',products=products,evidence=[a,b,c,d,e,f],status='partial',coverage_note='20 Evonik offerings total: prior nine biosurfactants plus 11 recombinant collagen/cellulose materials, three cellulose dressing lines, three hyaluronic-acid grades and three fermentation amino-acid ingredients. Materials and finished dressings overlap. TrypAMINO historical availability unresolved; no drug approval inferred from biomaterial clinical grade. Partial: further biotech ingredients/platforms, legacy epicite hydro naming, peptides/bioprocess offerings, semiconductor materials and battery materials remain.')
assert len(products)==11
(out/'batch-0388.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
